<template>
  <div class="safe-center-mail">
    <title-line :title="title" />
    <div class="content">
      <div class="box">
        <van-form validate-trigger="onSubmit" @submit="onSubmit">
          <div class="title">{{ $t('aqzx.aqzx54') }}</div>
          <van-field
            v-model="oldloginpwd"
            name="原密码"
            :type="passwordType"
            label=""
            :placeholder="$t('aqzx.aqzx25')"
            autocomplete="off"
            :rules="[{ required: true, message: $t('aqzx.aqzx25') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType">
                <van-icon v-if="passwordType==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx55') }}</div>
          <van-field
            v-model="newloginpwd"
            class="margin16"
            :type="passwordType1"
            name="新密码"
            label=""
            autocomplete="off"
            :placeholder="$t('aqzx.aqzx26')"
            :rules="[{ required: true, message: $t('aqzx.aqzx26') },
                     {pattern:/^(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])[a-zA-Z0-9]{6,20}$/,message:'请输入6至20位小写字母, 大写字母和数字的组合',trigger:'onBlur'}
            ]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType1">
                <van-icon v-if="passwordType1==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx55') }}</div>
          <van-field
            v-model="confirmpwd"
            class="margin16"
            :type="passwordType2"
            name="新密码"
            label=""
            autocomplete="off"
            :placeholder="$t('aqzx.aqzx27')"
            :rules="[{ required: true, message: $t('aqzx.aqzx27') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType2">
                <van-icon v-if="passwordType2==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <!-- <div class="tips" style="margin:20px 0 30px 0">
            <div class="warning_icon" />
            <span>为了保障您的账号和资金安全，请绑定邮箱</span>
          </div> -->
          <div style="margin: 40px auto 10px">
            <van-button
              class="btn-bg"
              block
              type="info"
              native-type="submit"
            >{{ $t('aqzx.aqzx28') }}</van-button>
          </div>
          <div class="forgetPsd"><span @click="goMore">{{ $t('aqzx.aqzx29') }}</span></div>
        </van-form>
      </div>
    </div>

  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { editloginpwd } from '@/api/safe'
export default {
  components: {
    TitleLine
  },
  props: {
  },
  data() {
    return {
      title: this.$t('aqzx.aqzx05'),
      oldloginpwd: '',
      newloginpwd: '',
      confirmpwd: '',
      passwordType: 'password',
      passwordType1: 'password',
      passwordType2: 'password',
      pattern: '^(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])[a-zA-Z0-9]{6,20}$'
    }
  },
  methods: {
    switchPasswordType() {
      this.passwordType = this.passwordType === 'password' ? 'text' : 'password'
    },
    switchPasswordType1() {
      this.passwordType1 = this.passwordType1 === 'password' ? 'text' : 'password'
    },
    switchPasswordType2() {
      this.passwordType2 = this.passwordType2 === 'password' ? 'text' : 'password'
    },
    goMore() {
      this.$router.push({ path: '/forgetLoginpwd' })
    },
    onSubmit() {
      if (this.newloginpwd !== this.confirmpwd) {
        this.$toast('两次输入的密码不一致')
        return false
      }
      editloginpwd({ oldloginpwd: this.oldloginpwd, newloginpwd: this.newloginpwd }).then(res => {
        if (res.status === '1') {
          this.$toast('设置成功')
          setTimeout(() => {
            this.$router.push({ path: '/safeCenter' })
          }, 2000)
        }
      })
    }
  }

}
</script>
<style lang="scss" scoped>
.safe-center-mail {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-position: 0% 0%;
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .containers{
    position: relative;
    // padding: 0px 30px 0px;
    }
    .content{
        margin: auto 28px;
        .box {
          margin-top: 36px;
          padding: 40px;
          border-radius: 28px;
          background: rgba(241, 229, 255,0.12);
          border-radius: 8px;
        .title {
            margin-bottom: 16px;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255,0.75);
            letter-spacing: 0;
            line-height: 40px;
            font-weight: 400;
        }
        .title:not(:first-child){
          margin-top: 40px;
        }
        .tips {
            color: #fff;
            position: relative;
            .warning_icon {
                position: absolute;
                top: 6px;
                width: 20px;
                height: 20px;
                background-image: url(~@/assets/portal/warning_icon.png);
                background-position: 0% 0%;
                background-size: 100% 100%;
                background-repeat: no-repeat;
            }
            span {
                margin-left: 28px;
            }
        }
        .forgetPsd{
            text-align: center;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: #00B7FF;
            font-weight: 400;
        }
     }
    }

}
</style>
